    return None
def _spell(s):
    out = []
    for ch in str(s):
        if ch.isdigit() or ch.isalpha():
            out.append(ch.upper())
        elif ch == '-':
            out.append('dash')
    return ', '.join(out)
STATUS_WORDS = dict(received='received and waiting', in_review='being reviewed', more_info_needed='waiting for information from you', approved='approved', rejected='not approved')
'''

