        return v2
    if fmt == 'date':
        m = re.fullmatch(r'(\d{1,2})[./ -](\d{1,2})[./ -](\d{4})', v)
        if m:
            v = '%04d-%02d-%02d' % (int(m.group(3)), int(m.group(2)), int(m.group(1)))
        try:
            return datetime.date.fromisoformat(v).isoformat()
        except Exception:
